n// 带标签的端口\nconst labeledNode = graph.addNode({\n  id: 'node-labeled',\n  label: '带标签端口',\n  x: 200,\n  y: 200,\n  shape: Shape.Rect,\n  style: {\n    width: 140,\n    height: 80,\n    backgroundColor: '#8b5cf6',\n    borderColor: '#7c3aed',\n    textColor: '#ffffff',\n  },\n});\nlabeledNode.addPort({\n  id: 'port-in',\n  position: 'left',\n  label: '输入',\n  visible: true,\n  style: { width: 14, height: 14, fillColor: '#22c55e', strokeColor: '#16a34a', strokeWidth: 2 },\n});\nlabeledNode.addPort({\n  id: 'port-out',\n  position: 'right',\n  label: '输出',\n  visible: true,\n  style: { width: 14, height: 14, fillColor: '#ef4444', strokeColor: '#dc2626', strokeWidth: 2 },\n});\n\nconsole.log('端口样式属性:');\nconsole.log('- width, height: 端口大小');\nconsole.log('- fillColor: 填充颜色');\nconsole.log('- strokeColor: 边框颜色');\nconsole.log('- strokeWidth: 边框宽度');"},{id:"example-5",title:"可见性控制",code:"// 示例 5: 端口可见性控制\nconst graph = new Graph({\n  container: container,\n  width: 600,\n  height: 300,\n  backgroundColor: '#f8fafc',\n  grid: { enabled: true, size: 20, color: '#e2e8f0' },\n});\n\n// 创建可切换端口可见性的节点\nconst toggleNode = graph.addNode({\n  id: 'node-toggle',\n  label: '可切换端口',\n  x: 300,\n  y: 150,\n  shape: Shape.Rect,\n  style: {\n    width: 160,\n    height: 100,\n    backgroundColor: '#8b5cf6',\n    borderColor: '#7c3aed',\n    textColor: '#ffffff',\n  },\n});\n\n// 添加端口（部分初始隐藏）\nconst ports = [\n  { id: 'port-top', pos: 'top', visible: true, color: '#22c55e' },\n  { id: 'port-right', pos: 'right', visible: false, color: '#f59e0b' },\n  { id: 'port-bottom', pos: 'bottom', visible: true, color: '#ef4444' },\n  { id: 'port-left', pos: 'left', visible: false, color: '#3b82f6' },\n];\n\nports.forEach((p) => {\n  toggleNode.addPort({\n    id: p.id,\n    position: p.pos,\n    visible: p.visible,\n    style: { fillColor: p.color, strokeColor: p.color, width: 12, height: 12, strokeWidth: 2 },\n  });\n});\n\n// 创建控制节点\nconst controlNode = graph.addNode({\n  id: 'node-control',\n  label: '控制器',\n  x: 100,\n  y: 150,\n  shape: Shape.Circle,\n  style: {\n    width: 80,\n    height: 80,\n    backgroundColor: '#14b8a6',\n    borderColor: '#0d9488',\n    textColor: '#ffffff',\n  },\n});\n\n// 连接可见端口\ncontrolNode.addPort({ id: 'port-out', position: 'right', visible: true });\ntoggleNode.addPort({ id: 'port-in', position: 'left', visible: true });\n\ngraph.addEdge({\n  id: 'edge-control',\n  source: { nodeId: 'node-control', portId: 'port-out' },\n  target: { nodeId: 'node-toggle', portId: 'port-in' },\n  type: EdgeType.Straight,\n  style: { stroke: '#64748b', strokeWidth: 2 },\n});\n\n// 演示切换可见性\nconsole.log('当前端口状态:');\nports.forEach((p) => {\n  const port = toggleNode.getPort(p.id);\n  console.log(`  ${p.id}: ${port?.getVisible() ? '可见' : '隐藏'}`);\n});\n\nconsole.log('\\n可以使用 port.setVisible(true/false) 切换可见性');"}],Fe=n(4114),Ye=n(9123);function Ve(e,t){(null==t||t>e.length)&&(t=e.length);for(var n=0,o=Array(t);n<t;n++)o[n]=e[n];return o}var $e=function(e){return{padding:"6px 12px",background:e,color:"white",border:"none",borderRadius:"4px",cursor:"pointer",fontSize:"13px"}};function Ke(e){return Ke="function"==typeof Symbol&&"symbol"==typeof Symbol.iterator?function(e){return typeof e}:function(e){return e&&"function"==typeof Symbol&&e.constructor===Symbol&&e!==Symbol.prototype?"symbol":typeof e},Ke(e)}function Xe(){var e,t,n="function"==typeof Symbol?Symbol:{},o=n.iterator||"@@iterator",r=n.toStringTag||"@@toStringTag";function i(n,o,r,i){var d=o&&o.prototype instanceof l?o:l,s=Object.create(d.prototype);return Je(s,"_invoke",function(n,o,r){var i,l,d,s=0,c=r||[],u=!1,f={p:0,n:0,v:e,a:h,f:h.bind(e,4),d:function(t,n){return i=t,l=0,d=e,f.n=n,a}};function h(n,o){for(l=n,d=o,t=0;!u&&s&&!r&&t<c.length;t++){var r,i=c[t],h=f.p,p=i[2];n>3?(r=p===o)&&(d=i[(l=i[4])?5:(l=3,3)],i[4]=i[5]=e):i[0]<=h&&((r=n<2&&h<i[1])?(l=0,f.v=o,f.n=i[1]):h<p&&(r=n<3||i[0]>o||o>p)&&(i[4]=n,i[5]=o,f.n=p,l=0))}if(r||n>1)return a;throw u=!0,o}return function(r,c,p){if(s>1)throw 